mat2 rot2(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

vec3 palette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(6.28318 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 ro = vec3(0.0, 1.0, -3.5);
    vec3 rd = normalize(vec3(uv, 1.4));
    float camAngle = iTime * 0.15;
    ro.xz = rot2(camAngle) * ro.xz;
    rd.xz = rot2(camAngle) * rd.xz;

    vec3 pos = ro;
    vec3 col = vec3(0.0);

    for (int i = 0; i < 48; i++) {
        float dist = length(pos);
        if (dist < 0.4) {
            break;
        }
        float r2 = max(dist * dist, 0.16);
        vec3 bend = (-pos / dist) / r2;
        rd = normalize(rd + bend * 0.05);
        pos += rd * 0.09;

        float distToPlane = abs(pos.y);
        float radius = length(pos.xz);
        float band = smoothstep(0.9, 1.15, radius) * smoothstep(2.6, 2.2, radius);
        if (band > 0.001) {
            float density = exp(-distToPlane * 9.0) * band;
            float angle = atan(pos.z, pos.x);
            float turb = noise(vec2(radius * 3.0 - iTime * 0.6, angle * 2.5));
            density *= (0.4 + 0.8 * turb);
            vec3 hotColor = palette(radius * 0.35 - iTime * 0.08, vec3(0.7, 0.35, 0.15), vec3(0.6, 0.4, 0.3), vec3(1.0, 0.9, 0.7), vec3(0.0, 0.1, 0.25));
            col += hotColor * density * 0.22;
        }
    }

    col = col / (1.0 + col);
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

