    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec2 p = vec2(uv.x, uv.y * 2.4);
    float r = length(p);
    float theta = atan(p.y, p.x);

    float horizonR = 0.42;
    float diskMask = smoothstep(0.5, 0.68, r) * smoothstep(1.5, 1.15, r);

    float spin = theta - iTime * 0.6 - r * 1.5;
    float shade = 0.6 + 0.4 * sin(spin * 6.0);
    float t = r * 0.6 - iTime * 0.15;
    vec3 hot = palette(t, vec3(0.65, 0.35, 0.2), vec3(0.55, 0.4, 0.35), vec3(1.0, 0.9, 0.6), vec3(0.0, 0.15, 0.3));

    vec3 col = hot * diskMask * shade * 1.3;

    float rim = smoothstep(horizonR + 0.14, horizonR, length(uv));
    col += vec3(1.0, 0.75, 0.4) * rim * 0.5;

    if (length(uv) < horizonR) {
        col = vec3(0.0);
    }

    col = col / (1.0 + col);
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

