float voronoi(vec2 p) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    float minDist = 8.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 neighbor = vec2(float(x), float(y));
            vec2 pt = hash22(ip + neighbor);
            pt = 0.5 + 0.5 * sin(iTime * 0.6 + 6.2831 * pt);
            vec2 diff = neighbor + pt - fp;
            float d = length(diff);
            minDist = min(minDist, d);
        }
    }
    return minDist;
}

