    vec3 hotc = vec3(1.0, 0.9, 0.6);
    vec3 white = vec3(1.0, 1.0, 0.95);
    vec3 c1 = mix(cool, mid, smoothstep(0.0, 0.4, t));
    vec3 c2 = mix(c1, hotc, smoothstep(0.35, 0.75, t));
    return mix(c2, white, smoothstep(0.7, 1.0, t));
}

