void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec3 ro = vec3(0.0, 0.9, -2.4);
    vec3 rd = normalize(vec3(uv, 1.3));
    float tilt = 0.55;
    mat2 tiltRot = mat2(cos(tilt), -sin(tilt), sin(tilt), cos(tilt));
    ro.yz = tiltRot * ro.yz;
    rd.yz = tiltRot * rd.yz;

    float horizonR = 0.5;
    vec3 pos = ro;
    vec3 vel = rd;
    vec3 accum = vec3(0.0);
    float alphaAcc = 0.0;

    for (int i = 0; i < 56; i++) {
        float dCenter = length(pos);
        if (dCenter < horizonR) {
            break;
        }
        vec3 toCenter = -pos / max(dCenter, 0.001);
        float bendStrength = 0.9 / (dCenter * dCenter + 0.15);
        vel = normalize(vel + toCenter * bendStrength * 0.05);
        pos += vel * 0.09;

        float distToPlane = abs(pos.y);
        float radial = length(pos.xz);
        float diskDensity = exp(-distToPlane * distToPlane * 40.0) * smoothstep(0.55, 0.75, radial) * smoothstep(2.0, 1.2, radial);

        float swirl = atan(pos.z, pos.x) * 3.0 - iTime * 1.5 + radial * 2.0;
        float turbulence = 0.6 + 0.4 * sin(swirl + noise(pos.xz * 2.0 + iTime * 0.2) * 6.0);

        vec3 emitCol = palette(radial * 0.7 - iTime * 0.1, vec3(0.75, 0.4, 0.15), vec3(0.5, 0.4, 0.3), vec3(1.0, 0.85, 0.6), vec3(0.05, 0.1, 0.25));
        float glow = diskDensity * turbulence;

        accum += emitCol * glow * (1.0 - alphaAcc) * 1.4;
        alphaAcc += glow * (1.0 - alphaAcc);

        if (alphaAcc > 0.98) {
            break;
        }
    }

    float horizonGlow = exp(-max(length(pos) - horizonR, 0.0) * 12.0) * step(length(pos), horizonR + 0.06);
    accum += vec3(1.0, 0.9, 0.8) * horizonGlow * 2.0;

    if (length(pos) < horizonR) {
        accum *= 0.15;
    }

    vec3 col = accum;
    col = col / (1.0 + col);
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}

