float voronoi(vec2 p, float t) {
    vec2 ip = floor(p);
    vec2 fp = fract(p);
    float minDist = 8.0;
    for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
            vec2 cell = vec2(float(x), float(y));
            vec2 cellPoint = hash22(ip + cell);
            cellPoint = 0.5 + 0.5 * sin(t + 6.2831 * cellPoint);
            vec2 diff = cell + cellPoint - fp;
            float d = length(diff);
            minDist = min(minDist, d);
        }
    }
    return minDist;
}

